int n;
const int maxn = 1e6 + 5;
vector<int> adj[maxn];
int h[maxn];
int st[maxn];
int en[maxn];
int tour[maxn];
int timer_ = 0;
long long a[maxn];
int ans[maxn];
vector<pair<int,int>> by_r[maxn];

struct Fenwick {
    int n;
    vector<int> bit;
    Fenwick(int _n = 0) { init(_n); }
    void init(int _n) { n = _n; bit.assign(n+1, 0); }
    void add(int idx, int delta) {
        for (; idx <= n; idx += idx & -idx) bit[idx] += delta;
    }
    int sum(int idx) {
        int s = 0;
        for (; idx > 0; idx -= idx & -idx) s += bit[idx];
        return s;
    }
    int range_sum(int l, int r) { if (r < l) return 0; return sum(r) - sum(l-1); }
};

void dfs(int root) {
    vector<pair<int,int>> stack;
    stack.reserve(n);
    stack.push_back({root, 0});
    vector<int> parent(n+1, 0);
    parent[root] = 0;
    while (!stack.empty()) {
        int u = stack.back().first;
        int &it = stack.back().second;
        if (it == 0) {
            h[u] = (parent[u] == 0 ? 0 : h[parent[u]] + 1);
            st[u] = ++timer_;
            tour[timer_] = u;
        }
        if (it < (int)adj[u].size()) {
            int v = adj[u][it++];
            if (v == parent[u]) continue;
            parent[v] = u;
            stack.push_back({v, 0});
        } else {
            en[u] = timer_;
            stack.pop_back();
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n)) return 0;
    for (int i = 1; i <= n; ++i) {
        long long val; cin >> val;
        a[i] = val;
    }
    for (int i = 1; i <= n - 1; ++i) {
        int u, v; cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    timer_ = 0;
    dfs(1);

    for (int i = 0; i <= n; ++i) by_r[i].clear();
    for (int i = 1; i <= n; ++i) {
        int l = st[i], r = en[i];
        by_r[r].push_back({l, i - 1});
    }

    Fenwick fenw(n);
    unordered_map<long long,int> last_seen;
    last_seen.reserve(n * 2);

    for (int i = 1; i <= n; ++i) {
        int node = tour[i];
        long long val = a[node];
        auto it = last_seen.find(val);
        if (it != last_seen.end()) {
            fenw.add(it->second, -1);
        }
        fenw.add(i, 1);
        last_seen[val] = i;

        for (auto &p : by_r[i]) {
            int l = p.first;
            int qi = p.second;
            ans[qi] = fenw.range_sum(l, i);
        }
    }

    for (int i = 0; i < n; ++i) {
        cout << ans[i] << ' ';
    }
}
